1	package netdiag
2	
3	import (
4		"fmt"
5		"os"
6		"reflect"
7		"strings"
8		"testing"
9		"time"
10	
11		tea "charm.land/bubbletea/v2"
12	
13		"github.com/anthnel/devdesk/internal/ports"
14		"github.com/anthnel/devdesk/internal/ui/components"
15		"github.com/anthnel/devdesk/internal/ui/keymap"
16		"github.com/anthnel/devdesk/internal/ui/testutil"
17	)
18	
19	// DEVDESK-711 (S-02b): on Linux and macOS K asks the process to stop first
20	// (SIGTERM), watches it for up to 5 s without blocking the screen, and only a
21	// second confirmation sends SIGKILL. The machine lives in PortsModel.stop; every
22	// step is a message carrying the generation of its stop, so a tick that outlives
23	// its stop touches nothing.
24	//
25	// No test here reaches ports.Terminate, ports.Probe or ports.Kill: every model
26	// installs a fakeProcs, and the probe ticks are never waited for. The messages a
27	// tick or a signal would deliver are built here, with the generation read from
28	// the model and the instants chosen by the test (stopT0 plus an offset), so no
29	// test sleeps. A test that drains a Cmd shortens the footer timer first
30	// (testutil.FastTimers, Rule 128), and none drains a probe tick except the
31	// Rule 110 one, which shortens stopProbeEvery too.
32	
33	// stopT0 is the instant the SIGTERM call returned in these tests: the deadline
34	// is stopT0 plus the 5 s grace.
35	var stopT0 = time.Unix(1_700_000_000, 0)
36	
37	// The sentences of the story, written out in full so that a drift in the
38	// constants of this package fails a test instead of following them.
39	const (
40		stoppedNginx        = "nginx (812) stopped"
41		stoppedWaitingNginx = "Stopped waiting for nginx (812) — the stop request was already sent"
42		notForcedNginx      = "nginx (812) left running — no SIGKILL sent"
43		forceBody           = "nginx (PID 812) did not exit within 5 s. Force kill (SIGKILL)? It gets no chance to shut down cleanly."
44		stopBody            = "Ask nginx (PID 812) to stop? Sends SIGTERM and waits up to 5 s. You can force it afterwards."
45		anotherStopText     = "Another stop is already in progress"
46		stopPendingHereText = "This process is already being stopped"
47	)
48	
49	// stopRows are three listed processes; the cursor starts on nginx (PID 812).
50	func stopRows() []ports.Socket {
51		return []ports.Socket{sock("812", "nginx"), sock("4242", "node"), sock("1204", "sshd")}
52	}
53	
54	// stopModelWith is a Linux model whose cursor is on rows[0] and whose stop
55	// confirmation is open, at the given width.
56	func stopModelWith(t *testing.T, width int, rows []ports.Socket) (*Model, *fakeProcs) {
57		t.Helper()
58		m, procs := identityModel(t, false, rows...)
59		m = feed(t, m, tea.WindowSizeMsg{Width: width, Height: 40})
60		m = feed(t, m, testutil.Key(keymap.Kill))
61		if m.portsModel.confirmModal == nil {
62			t.Fatalf("setup: K on %s did not open the confirmation", rows[0].Process)
63		}
64		return m, procs
65	}
66	
67	// stopModel is stopModelWith on nginx, wide.
68	func stopModel(t *testing.T) (*Model, *fakeProcs) {
69		t.Helper()
70		return stopModelWith(t, 160, stopRows())
71	}
72	
73	// signalling answers Yes: the SIGTERM is in flight. It returns the command Yes
74	// returned, which is the SIGTERM itself and has not been run.
75	func signalling(t *testing.T) (*Model, tea.Cmd, *fakeProcs) {
76		t.Helper()
77		m, procs := stopModel(t)
78		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
79		if m.portsModel.stop == nil || m.portsModel.stop.phase != stopSignalling {
80			t.Fatalf("setup: after Yes the stop is %+v, want phase stopSignalling", m.portsModel.stop)
81		}
82		return m, cmd, procs
83	}
84	
85	// sent is signalling with the SIGTERM actually run against the fake, so the
86	// fake has recorded the call a real SIGTERM would have been. The result the run
87	// produced is dropped: the tests feed their own, with an instant they chose.
88	func sent(t *testing.T) (*Model, *fakeProcs) {
89		t.Helper()
90		m, cmd, procs := signalling(t)
91		runTerm(t, cmd)
92		return m, procs
93	}
94	
95	// termDelivered feeds the result of the SIGTERM of the stop in progress, which
96	// returned at instant at.
97	func termDelivered(t *testing.T, m *Model, at time.Time) (*Model, tea.Cmd) {
98		t.Helper()
99		s := m.portsModel.stop
100		if s == nil {
101			t.Fatal("setup: no stop in progress to deliver a SIGTERM result to")
102		}
103		return step(t, m, portsTermResultMsg{gen: s.gen, pid: s.target.PID, process: s.target.Process, at: at})
104	}
105	
106	// waiting is a model whose SIGTERM was delivered at stopT0: the wait has begun.
107	func waiting(t *testing.T) (*Model, *fakeProcs) {
108		t.Helper()
109		m, procs := sent(t)
110		m, _ = termDelivered(t, m, stopT0)
111		if m.portsModel.stop == nil || m.portsModel.stop.phase != stopWaiting {
112			t.Fatalf("setup: the stop is %+v, want phase stopWaiting", m.portsModel.stop)
113		}
114		return m, procs
115	}
116	
117	// probeAt feeds what the tick at instant at read: the stop in progress is
118	// probed and found in state l.
119	func probeAt(t *testing.T, m *Model, at time.Time, l ports.Liveness, err error) (*Model, tea.Cmd) {
120		t.Helper()
121		s := m.portsModel.stop
122		if s == nil {
123			t.Fatal("setup: no stop in progress to probe")
124		}
125		return step(t, m, portsStopProbeMsg{gen: s.gen, at: at, liveness: l, err: err})
126	}
127	
128	// afterGrace is the instant of the first tick that finds the grace used up.
129	var afterGrace = stopT0.Add(5 * time.Second)
130	
131	// askingToForce is a model whose process still ran at the deadline: the second
132	// confirmation is open.
133	func askingToForce(t *testing.T) (*Model, *fakeProcs) {
134		t.Helper()
135		m, procs := waiting(t)
136		m, _ = probeAt(t, m, afterGrace, ports.ProcessRunning, nil)
137		if m.portsModel.stop == nil || m.portsModel.stop.phase != stopAskingForce || m.portsModel.confirmModal == nil {
138			t.Fatalf("setup: the stop is %+v with modal %v, want the second confirmation open", m.portsModel.stop, m.portsModel.confirmModal != nil)
139		}
140		return m, procs
141	}
142	
143	// forcing answers Yes to the second confirmation: the SIGKILL is in flight. It
144	// returns the SIGKILL command, not run.
145	func forcing(t *testing.T) (*Model, tea.Cmd, *fakeProcs) {
146		t.Helper()
147		m, procs := askingToForce(t)
148		m, cmd := step(t, m, components.ConfirmModalYesMsg{})
149		if m.portsModel.stop == nil || m.portsModel.stop.phase != stopForcing {
150			t.Fatalf("setup: after the second Yes the stop is %+v, want phase stopForcing", m.portsModel.stop)
151		}
152		return m, cmd, procs
153	}
154	
155	// busyOf is the label the row of pid carries, or "" when it is not busy.
156	func busyOf(m *Model, pid string) string {
157		label, _ := m.portsModel.table.BusyLabel(pid)
158		return label
159	}
160	
161	// refreshes drains cmd and counts the reads of the table it asked for. The
162	// caller shortened the footer timer.
163	func refreshes(cmd tea.Cmd) int { return countRefreshes(testutil.Msgs(cmd)) }
164	
165	// ── Criterion 1: the first confirmation announces two steps ──────────────────
166	
167	func TestTheStopConfirmationAnnouncesTwoSteps(t *testing.T) {
168		m, _ := stopModel(t)
169	
170		if got := modalTitle(m); got != "Stop Process" {
171			t.Errorf("title = %q, want %q", got, "Stop Process")
172		}
173		if got := squash(modalBody(m)); got != stopBody {
174			t.Errorf("body = %q, want %q", got, stopBody)
175		}
176		if strings.Contains(modalBody(m), "SIGKILL") {
177			t.Errorf("the first confirmation mentions SIGKILL, which it does not offer: %q", modalBody(m))
178		}
179		if got := stopPrompt(killTarget{PID: "812", Process: "nginx"}); got != "Ask nginx (PID 812) to stop?\n\nSends SIGTERM and waits up to 5 s. You can force it afterwards." {
180			t.Errorf("stopPrompt = %q", got)
181		}
182	}
183	
184	func TestYesSendsSIGTERMNotSIGKILL(t *testing.T) {
185		m, cmd, procs := signalling(t)
186	
187		res := runTerm(t, cmd)
188	
189		if !reflect.DeepEqual(procs.terminated, []string{"812"}) {
190			t.Errorf("SIGTERM went to %v, want [812]", procs.terminated)
191		}
192		if want := []ports.Identity{idOf("812")}; !reflect.DeepEqual(procs.terminatedWith, want) {
193			t.Errorf("SIGTERM verified against %v, want the identity captured at the confirmation %v", procs.terminatedWith, want)
194		}
195		if len(procs.killed) != 0 {
196			t.Errorf("SIGKILL went to %v on the first Yes", procs.killed)
197		}
198		if res.gen != m.portsModel.stop.gen || res.gen == 0 {
199			t.Errorf("result generation = %d, stop generation = %d, want one non-zero generation", res.gen, m.portsModel.stop.gen)
200		}
201		if res.pid != "812" || res.process != "nginx" {
202			t.Errorf("result = (pid %q, process %q), want (812, nginx)", res.pid, res.process)
203		}
204		if res.at.IsZero() {
205			t.Error("the result carries no instant: the deadline has nothing to start from")
206		}
207		if got := busyOf(m, "812"); got != "Stopping nginx (812)" {
208			t.Errorf("busy label = %q, want %q", got, "Stopping nginx (812)")
209		}
210		if m.portsModel.confirmModal != nil || m.portsModel.pendingKill != nil {
211			t.Error("the confirmation or its captured target survived Yes")
212		}
213		if want := (killTarget{PID: "812", Process: "nginx", Identity: idOf("812")}); m.portsModel.stop.target != want {
214			t.Errorf("stop target = %+v, want %+v", m.portsModel.stop.target, want)
215		}
216	}
217	
218	// ── Criterion 2: leaving within the grace, or a zombie, is a stop ────────────
219	
220	func TestADeliveredSIGTERMStartsTheWait(t *testing.T) {
221		m, _, procs := signalling(t)
222	
223		m, cmd := termDelivered(t, m, stopT0)
224	
225		s := m.portsModel.stop
226		if s == nil || s.phase != stopWaiting {
227			t.Fatalf("stop = %+v, want phase stopWaiting", s)
228		}
229		if want := stopT0.Add(5 * time.Second); !s.deadline.Equal(want) {
230			t.Errorf("deadline = %v, want %v (5 s after the signal returned)", s.deadline, want)
231		}
232		if got := busyOf(m, "812"); got != "Waiting for nginx (812) to exit" {
233			t.Errorf("busy label = %q, want %q", got, "Waiting for nginx (812) to exit")
234		}
235		if cmd == nil {
236			t.Error("no command returned: nothing would probe the process")
237		}
238		if m.portsModel.confirmModal != nil {
239			t.Error("a confirmation opened while the wait begins")
240		}
241		if len(procs.probed) != 0 || len(procs.killed) != 0 {
242			t.Errorf("probed %v and killed %v before any tick ran", procs.probed, procs.killed)
243		}
244	}
245	
246	func TestAnExitWithinTheGraceIsAStop(t *testing.T) {
247		testutil.FastTimers(t, &components.FooterMsgDuration)
248		m, procs := waiting(t)
249	
250		m, cmd := probeAt(t, m, stopT0.Add(time.Second), ports.ProcessExited, nil)
251	
252		if m.portsModel.stop != nil {
253			t.Errorf("stop = %+v after the process exited, want none", m.portsModel.stop)
254		}
255		if m.portsModel.table.IsBusy("812") {
256			t.Error("the row is still busy after the process exited")
257		}
258		if got := m.portsModel.footer.Text(); got != stoppedNginx {
259			t.Errorf("footer = %q, want %q", got, stoppedNginx)
260		}
261		if got := m.portsModel.footer.Level(); got != components.LevelInfo {
262			t.Errorf("footer level = %v, want Info", got)
263		}
264		if n := refreshes(cmd); n != 1 {
265			t.Errorf("the stop asked for %d reads of the table, want 1: the row should go without waiting for the next tick", n)
266		}
267		if m.portsModel.confirmModal != nil {
268			t.Error("a second confirmation opened for a process that left")
269		}
270		if len(procs.killed) != 0 {
271			t.Errorf("SIGKILL went to %v for a process that left on its own", procs.killed)
272		}
273	}
274	
275	// A zombie has exited and its parent has not reaped it yet: the stop did its
276	// job, whatever ps still lists.
277	func TestAZombieCountsAsStopped(t *testing.T) {
278		testutil.FastTimers(t, &components.FooterMsgDuration)
279		m, procs := waiting(t)
280	
281		m, cmd := probeAt(t, m, stopT0.Add(time.Second), ports.ProcessZombie, nil)
282	
283		if m.portsModel.stop != nil || m.portsModel.table.IsBusy("812") {
284			t.Errorf("a zombie left the stop %+v pending, busy = %v", m.portsModel.stop, m.portsModel.table.IsBusy("812"))
285		}
286		if got := m.portsModel.footer.Text(); got != stoppedNginx {
287			t.Errorf("footer = %q, want %q", got, stoppedNginx)
288		}
289		if n := refreshes(cmd); n != 1 {
290			t.Errorf("the stop asked for %d reads of the table, want 1", n)
291		}
292		if m.portsModel.confirmModal != nil || len(procs.killed) != 0 {
293			t.Errorf("modal open = %v, killed = %v: a zombie is not forced", m.portsModel.confirmModal != nil, procs.killed)
294		}
295	}
296	
297	func TestStillRunningBeforeTheDeadlineProbesAgain(t *testing.T) {
298		m, procs := waiting(t)
299	
300		m, cmd := probeAt(t, m, stopT0.Add(4750*time.Millisecond), ports.ProcessRunning, nil)
301	
302		if s := m.portsModel.stop; s == nil || s.phase != stopWaiting {
303			t.Fatalf("stop = %+v, want it still waiting", s)
304		}
305		if cmd == nil {
306			t.Error("no command returned: the next tick would never come")
307		}
308		if m.portsModel.confirmModal != nil {
309			t.Error("the second confirmation opened before the deadline")
310		}
311		if got := busyOf(m, "812"); got != "Waiting for nginx (812) to exit" {
312			t.Errorf("busy label = %q, want it unchanged while waiting", got)
313		}
314		if len(procs.killed) != 0 {
315			t.Errorf("SIGKILL went to %v before the deadline", procs.killed)
316		}
317	}
318	
319	// ── Criterion 3: no SIGKILL without a second confirmation ────────────────────
320	
321	func TestStillRunningAtTheDeadlineAsksToForce(t *testing.T) {
322		m, procs := waiting(t)
323	
324		m, _ = probeAt(t, m, afterGrace, ports.ProcessRunning, nil)
325	
326		if s := m.portsModel.stop; s == nil || s.phase != stopAskingForce {
327			t.Fatalf("stop = %+v, want phase stopAskingForce", s)
328		}
329		if m.portsModel.confirmModal == nil {
330			t.Fatal("the second confirmation did not open")

330			t.Fatal("the second confirmation did not open")
331		}
332		if got := modalTitle(m); got != "Force Kill" {
333			t.Errorf("title = %q, want %q", got, "Force Kill")
334		}
335		if got := squash(modalBody(m)); got != forceBody {
336			t.Errorf("body = %q, want %q", got, forceBody)
337		}
