20	// DEVDESK-717 (step 3 of DEVDESK-708): the confirmation of the Ports tab acts on
21	// the target it captured when it opened (S-01a criteria 5 and 6, bug
22	// DEVDESK-714), and says the truth on Windows (S-02a criteria 1 to 4).
23	//
24	// No test here reaches ports.Kill: every model installs a fake processOps whose
25	// kill only records the PID it was asked to signal.
26	
27	// fakeProcs records the PIDs the Ports tab asked to signal.
28	type fakeProcs struct {
29		killed []string
30		// killedWith records the identity each signal was asked to verify against
31		// (DEVDESK-709), in the order of killed.
32		killedWith []ports.Identity
33		err        error
34		// confirmed is the identity the confirmation reads for a PID, confirmErr the
35		// error it returns instead, confirmAsked every PID it was asked about. A PID
36		// in neither gets the identity it was listed with (DEVDESK-709).
37		confirmed    map[string]ports.Identity
38		confirmErr   map[string]error
39		confirmAsked []string
40		// protect is the verdict per PID; a PID not in it is Unprotected. asked
41		// records every PID the model asked about, in order (DEVDESK-718).
42		protect map[string]ports.Protection
43		asked   []string
44	
45		// S-02b (DEVDESK-711): the first signal of a stop is SIGTERM, then the table
46		// probes the process, and SIGKILL only follows a second confirmation.
47		// terminated records the PIDs asked to stop (ports.Terminate), terminatedWith
48		// the identity each was verified against; termErr is what terminate returns.
49		terminated     []string
50		terminatedWith []ports.Identity
51		termErr        error
52		// probed records every PID probed and the identity it was compared with.
53		// probeAnswer is the verdict per PID (a PID not in it is ProcessRunning, the
54		// zero value) and probeErr the error every probe returns with it.
55		probed      []string
56		probedWith  []ports.Identity
57		probeAnswer map[string]ports.Liveness
58		probeErr    error
59	}
60	
61	// signals is every PID a signal was asked for, SIGTERM and SIGKILL alike: what a
62	// test that expects nothing to leave asserts is empty.
63	func (f *fakeProcs) signals() []string {
64		return append(append([]string(nil), f.terminated...), f.killed...)
65	}
66	
67	func (f *fakeProcs) ops(windows bool) processOps {
68		return processOps{
69			protection: func(pid string) ports.Protection {
70				f.asked = append(f.asked, pid)
71				return f.protect[pid]
72			},
73			confirm: func(pid string, listed ports.Identity) (ports.Identity, error) {
74				f.confirmAsked = append(f.confirmAsked, pid)
75				if err := f.confirmErr[pid]; err != nil {
76					return ports.Identity{}, err
77				}
78				if id, ok := f.confirmed[pid]; ok {
79					return id, nil
80				}
81				return listed, nil
82			},
83			terminate: func(pid string, listed ports.Identity) error {
84				f.terminated = append(f.terminated, pid)
85				f.terminatedWith = append(f.terminatedWith, listed)
86				return f.termErr
87			},
88			probe: func(pid string, listed ports.Identity) (ports.Liveness, error) {
89				f.probed = append(f.probed, pid)
90				f.probedWith = append(f.probedWith, listed)
91				return f.probeAnswer[pid], f.probeErr
92			},
93			kill: func(pid string, listed ports.Identity) error {
94				f.killed = append(f.killed, pid)
95				f.killedWith = append(f.killedWith, listed)
96				return f.err
97			},
98			windows: windows,
99		}
100	}
