102	// protectAs makes the fake say p about pid from now on.
103	func (f *fakeProcs) protectAs(pid string, p ports.Protection) {
104		if f.protect == nil {
105			f.protect = map[string]ports.Protection{}
106		}
107		f.protect[pid] = p
108	}
