117	// idOf is the identity the fixtures give the process with this PID: the PID
118	// itself, so two rows of one process agree and two processes differ. A row with
119	// no PID has none (DEVDESK-709).
120	func idOf(pid string) ports.Identity {
121		n, err := strconv.ParseUint(pid, 10, 64)
122		if err != nil {
123			return ports.Identity{}
124		}
125		return ports.IdentityForTest(n)
126	}
