134	// sockWith is sock with an explicit identity: the zero value for a row DevDesk
135	// could not read, a deferred one for a Windows listing over its budget, or the
136	// stamp of another process holding the same PID.
137	func sockWith(pid, process string, id ports.Identity) ports.Socket {
138		return ports.Socket{
139			Protocol: "tcp", State: "LISTEN", LocalAddr: "0.0.0.0:" + pid, PeerAddr: "0.0.0.0:*",
140			PID: pid, Process: process, Identity: id,
141		}
142	}
