19	// DEVDESK-711 (S-02b): work netdiag started finishes in netdiag. A stop on the
20	// Ports tab is a chain of messages (the SIGTERM result, the probe ticks, the
21	// SIGKILL result) that arrive whenever the user is, so the router hands them to
22	// netdiag whether or not it is on screen. A message dropped because the user
23	// walked away leaves a row busy and, with the stop pending, K greyed for good.
24	//
25	// These tests call the views' Update directly and never run the Cmds they
26	// return: the PID is above the kernel's pid_max, so even a Cmd that slipped
27	// through could not signal a real process, and none sleeps on a footer timer.
28	
29	// ghostPID is a PID no process can hold (above pid_max).
30	const ghostPID = "4194305"
31	
32	// seedStop puts a stop in flight on the Ports tab of a netdiag view the router
33	// holds, off screen: seedNetdiagFooter's row, with the router left on the
34	// dashboard. It returns the view.
35	func seedStop(t *testing.T, a *App) *netdiag.Model {
36		t.Helper()
37		if runtime.GOOS == "windows" {
38			t.Skip("Windows has no two-step stop: the kill result is covered by TestNetdiagWorkReachesItOffScreen on the other platforms")
39		}
40		seedNetdiagFooter(t, a)
41		held, ok := a.views[command.ViewNetdiag].(*netdiag.Model)
42		if !ok {
43			t.Fatalf("the router holds a %T", a.views[command.ViewNetdiag])
44		}
45		if !held.WantsBlink() {
46			t.Fatal("setup: no stop is marked on the row")
47		}
48		return held
49	}
50	
51	// The result of a signal started in netdiag reaches it while another view is on
52	// screen: the row stops being busy and the dot goes out.
53	func TestNetdiagWorkReachesItOffScreen(t *testing.T) {
54		a := routerAt(t, &bareView{}, 180, 40)
55		held := seedStop(t, a)
56		if a.currentView != command.ViewDashboard {
57			t.Fatalf("setup: the current view is %s, want the dashboard", a.currentView)
58		}
59	
60		a.Update(netdiag.NewPortsKillResultMsg(ghostPID))
61	
62		if held.WantsBlink() {
63			t.Error("the row of the PID is still busy: the result sent while netdiag was off screen was dropped")
64		}
65		if got := a.views[command.ViewNetdiag]; got != held {
66			t.Errorf("the router now holds %T %v, want the same view", got, got)
67		}
68		if a.currentView != command.ViewDashboard {
69			t.Errorf("current view = %s: delivering the result changed which view is on screen", a.currentView)
70		}
71		row := portsRow(t, a)
72		for _, on := range []bool{true, false} {
73			if g := indicator.Glyph(indicator.Running, on); strings.Contains(row, g) {
74				t.Errorf("the row still shows the running glyph %q: %q", g, row)
75			}
76		}
77	}
