111	// Only netdiag's own messages take this road: nothing the router already routes
112	// by another rule may implement the interface, or it would be redirected.
113	func TestOnlyNetdiagWorkIsBackgroundMessage(t *testing.T) {
114		if _, ok := netdiag.NewPortsKillResultMsg(ghostPID).(netdiag.BackgroundMsg); !ok {
