144	// nodeFirst and nodeLast are the same sockets in two orders: the refresh of the
145	// table reorders them while a confirmation is open (DEVDESK-714).
146	func nodeFirst() []ports.Socket {
147		return []ports.Socket{sock("4242", "node"), sock("812", "sshd"), sock("1204", "nginx")}
148	}
