211	func modalLines(m *Model) []string {
212		var out []string
213		for _, l := range strings.Split(ansi.Strip(m.portsModel.confirmModal.View()), "\n") {
214			l = strings.TrimSpace(strings.Trim(strings.TrimSpace(l), "│┌┐└┘─"))
215			if strings.Contains(l, "Yes") && strings.Contains(l, "No") {
216				break
217			}
218			out = append(out, l)
219		}
220		for len(out) > 0 && out[0] == "" {
221			out = out[1:]
222		}
223		for len(out) > 0 && out[len(out)-1] == "" {
224			out = out[:len(out)-1]
225		}
226		return out
227	}
