79	// With netdiag on screen the same message still arrives, through the active
80	// view as every message did before.
81	func TestNetdiagWorkOnScreenStillGoesThroughTheActiveView(t *testing.T) {
82		a := routerAt(t, &bareView{}, 180, 40)
83		held := seedStop(t, a)
84		a.currentView = command.ViewNetdiag
85	
86		a.Update(netdiag.NewPortsKillResultMsg(ghostPID))
87	
88		if held.WantsBlink() {
89			t.Error("the row of the PID is still busy: a result sent to the active netdiag view was dropped")
90		}
91		if a.currentView != command.ViewNetdiag {
92			t.Errorf("current view = %s, want netdiag to stay on screen", a.currentView)
93		}
94	}
