96	// Nothing was started if netdiag was never opened: the message finds no view and
97	// creates none (routeToView's rule).
98	func TestNetdiagWorkWithNoViewIsDropped(t *testing.T) {
99		a := routerAt(t, &bareView{}, 180, 40)
