103		if _, exists := a.views[command.ViewNetdiag]; exists {
104			t.Error("a result with no view behind it created one")
105		}
106		if a.currentView != command.ViewDashboard {
107			t.Errorf("current view = %s, want the dashboard", a.currentView)
108		}
109	}
