111	// Only netdiag's own messages take this road: nothing the router already routes
112	// by another rule may implement the interface, or it would be redirected.
113	func TestOnlyNetdiagWorkIsBackgroundMessage(t *testing.T) {
114		if _, ok := netdiag.NewPortsKillResultMsg(ghostPID).(netdiag.BackgroundMsg); !ok {
115			t.Fatal("a kill result is not a netdiag.BackgroundMsg: the router cannot recognize it")
116		}
117		for name, msg := range map[string]tea.Msg{
118			"a key":            testutil.Key("a"),
119			"a resize":         tea.WindowSizeMsg{Width: 80, Height: 24},
120			"a ports read":     netdiag.NewPortsDataMsg([]ports.Socket{{PID: ghostPID}}),
121			"a netdiag open":   netdiag.OpenRequestMsg{},
122			"a nil message":    nil,
123			"an unrelated one": struct{ id int }{1},
124		} {
125			if _, ok := msg.(netdiag.BackgroundMsg); ok {
126				t.Errorf("%s is a netdiag.BackgroundMsg: the router would reroute it", name)
127			}
