131	// A stop in flight protects the netdiag view that was opened from another view
132	// (status's H) from being thrown away when the user names it again, like a run in
133	// flight does: dropping it would discard the wait without a word.
134	func TestNamingNetdiagDoesNotDropAStopInFlight(t *testing.T) {
135		if runtime.GOOS == "windows" {
