144			tea.WindowSizeMsg{Width: a.width, Height: a.height},
145			testutil.Key("tab"), // the Ports tab
146			netdiag.NewPortsDataMsg([]ports.Socket{{
147				Protocol: "tcp", State: "LISTEN", LocalAddr: "127.0.0.1:9", PID: ghostPID, Process: "ghost",
148				Identity: ports.IdentityForTest(1),
149			}}),
150			testutil.Key(keymap.Kill),
151			components.ConfirmModalYesMsg{},
152		} {
153			held.Update(msg)
154		}
155		if !held.Running() {
